import { isEmpty, isUndefined } from 'lodash-es';

import {
  ESTIMATED_SMALL_SIZE_VIRTUAL_HEIGHT,
  ESTIMATED_MEDIUM_SIZE_VIRTUAL_HEIGHT,
  ESTIMATED_LENGTH_BREAKLINE,
  ESTIMATED_HEADER_HEIGHT,
  ESTIMATED_BIG_SIZE_VIRTUAL_HEIGHT,
  DEFAULT_VIRTUALIZED_HEIGHT,
} from '../components/tooltip/constants-virtualization-list.js';
import { AnnotationGroup } from '../types/annotations.js';

/**
 * Based on the data estimates the height of the virtual row to virtualize the list
 *
 * @param index
 * @param annotationGroup
 *
 * @returns number - estimated height for virtual row
 */
export function sumAnnotationsHeights(
  index: number,
  annotationGroup: AnnotationGroup[],
) {
  return (
    (annotationGroup?.[index]?.annotations
      ?.map((annotation) => {
        const hasDescription = !isUndefined(annotation.description);
        const hasTitle = !isEmpty(annotation.title);
        const hasLongDescription =
          hasDescription &&
          annotation.description!.length > ESTIMATED_LENGTH_BREAKLINE;
        const hasLongTitle =
          annotation.title?.length > ESTIMATED_LENGTH_BREAKLINE;
        if (hasDescription && hasTitle) {
          return hasLongDescription && hasLongTitle
            ? ESTIMATED_BIG_SIZE_VIRTUAL_HEIGHT
            : hasLongDescription || hasLongTitle
            ? ESTIMATED_MEDIUM_SIZE_VIRTUAL_HEIGHT
            : ESTIMATED_SMALL_SIZE_VIRTUAL_HEIGHT;
        } else if (hasDescription || hasTitle) {
          return hasLongDescription || hasLongTitle
            ? ESTIMATED_SMALL_SIZE_VIRTUAL_HEIGHT
            : DEFAULT_VIRTUALIZED_HEIGHT;
        } else {
          return DEFAULT_VIRTUALIZED_HEIGHT;
        }
      })
      .reduce((a, b) => a + b, 0) ?? DEFAULT_VIRTUALIZED_HEIGHT) +
    ESTIMATED_HEADER_HEIGHT
  );
}
